"use client";

import React, { useState } from "react";
import { usePathname, useRouter } from "next/navigation";
import Link from "next/link";
import { Menu, X, ArrowLeft } from "lucide-react";

import {
  Info,
  Mail,
  HelpCircle,
  Truck,
  RefreshCcw,
  Shield,
  FileText,
  Ruler,
  MessageCircle,
} from "lucide-react";

export const helpSections = [
  {
    id: "about",
    label: "About Us",
    href: "/help/about",
    icon: React.createElement(Info, { size: 22 }),
    tagline: "Our brand philosophy.",
  },
  {
    id: "contact",
    label: "Contact Us",
    href: "/help/contact",
    icon: React.createElement(Mail, { size: 22 }),
    tagline: "Talk to our team.",
  },
  {
    id: "faq",
    label: "FAQ",
    href: "/help/faq",
    icon: React.createElement(HelpCircle, { size: 22 }),
    tagline: "Quick answers.",
  },
  {
    id: "shipping",
    label: "Shipping",
    href: "/help/shipping",
    icon: React.createElement(Truck, { size: 22 }),
    tagline: "Delivery & Tracking.",
  },
  {
    id: "returns",
    label: "Returns",
    href: "/help/returns",
    icon: React.createElement(RefreshCcw, { size: 22 }),
    tagline: "Easy return process.",
  },
  {
    id: "size-guide",
    label: "Size Guide",
    href: "/help/size-guide",
    icon: React.createElement(Ruler, { size: 22 }),
    tagline: "Find your perfect fit.",
  },
  {
    id: "refund-policy",
    label: "Refund Policy",
    href: "/help/refund-policy",
    icon: React.createElement(Shield, { size: 22 }),
    tagline: "Money-back terms.",
  },
  {
    id: "privacy-policy",
    label: "Privacy",
    href: "/help/privacy-policy",
    icon: React.createElement(Shield, { size: 22 }),
    tagline: "Data protection.",
  },
  {
    id: "terms",
    label: "Terms",
    href: "/help/terms",
    icon: React.createElement(FileText, { size: 22 }),
    tagline: "Legal agreement.",
  },
];

export default function HelpLayout({
  children,
}: {
  children: React.ReactNode;
}) {
  const [isMenuOpen, setIsMenuOpen] = useState(false);
  const pathname = usePathname();
  const router = useRouter();

  const activeSection = helpSections.find((s) => s.href === pathname);

  return (
    <div className="min-h-screen bg-background text-foreground selection:bg-brand selection:text-white">
      {/* --- STICKY NAV BAR --- */}
      <header className="fixed top-0 z-50 w-full border-b border-border bg-background/80 backdrop-blur-md h-20">
        <div className="max-w-7xl mx-auto h-full px-6 flex items-center justify-between">
          <button
            onClick={() => router.back()}
            className="p-2 hover:bg-background-muted rounded-full transition-colors"
          >
            <ArrowLeft size={22} />
          </button>

          <div className="text-center">
            <p className="text-[9px] uppercase tracking-[0.4em] text-foreground-subtle font-black mb-0.5">
              Fashion Friday
            </p>
            <h1 className="text-xs font-black uppercase tracking-widest">
              {activeSection?.label || "Help Center"}
            </h1>
          </div>

          <button
            onClick={() => setIsMenuOpen(true)}
            className="flex items-center gap-3 group"
          >
            <span className="text-[10px] font-black uppercase tracking-widest hidden sm:block">
              Menu
            </span>
            <div className="p-2.5 bg-foreground text-background rounded-full group-hover:bg-brand group-hover:text-white transition-all">
              <Menu size={18} />
            </div>
          </button>
        </div>
      </header>

      {/* --- OVERLAY MENU --- */}
      <div
        className={`fixed inset-0 z-[60] bg-background transition-transform duration-500 ease-in-out ${
          isMenuOpen ? "translate-x-0" : "translate-x-full"
        }`}
      >
        <div className="h-20 px-6 flex items-center justify-end max-w-7xl mx-auto">
          <button
            onClick={() => setIsMenuOpen(false)}
            className="p-3 hover:bg-background-muted rounded-full transition-colors"
          >
            <X size={32} />
          </button>
        </div>
        <div className="max-w-3xl mx-auto px-6 py-12">
          <nav className="grid grid-cols-1 md:grid-cols-2 gap-3">
            {helpSections.map((item) => (
              <Link
                key={item.id}
                href={item.href}
                onClick={() => setIsMenuOpen(false)}
                className={`flex items-center gap-4 p-6 rounded-3xl border transition-all ${
                  pathname === item.href
                    ? "bg-brand text-white border-brand"
                    : "bg-background-muted border-transparent hover:border-border"
                }`}
              >
                <div className="p-3 bg-background rounded-xl text-foreground italic">
                  {item.icon}
                </div>
                <span className="font-black uppercase tracking-tighter text-lg">
                  {item.label}
                </span>
              </Link>
            ))}
          </nav>
        </div>
      </div>

      <main className="pt-20">{children}</main>
    </div>
  );
}
